import * as THREE from 'three';
import {configureSourceTangentMaterial,injectSourceTangentFrame,sourceTangentProgramKey} from './source-tangent-frame.js';

// Generated by tools/materials/catwalk2-prepare.py. Source material math and
// renderer mappings are deliberately recorded separately in the asset document.
export const CATWALK2_GLSL = "// LOCAL-CATWALK2-SHADER-001. Deferred PS 2b6d233517, paired VS ea0522bd70.\n// Source absolute world XZ drives grunge; source UV0 drives authored normals.\nstruct Catwalk2Surface {\n  vec3 color;\n  vec3 tangentNormal;\n  float smoothness;\n};\nCatwalk2Surface sampleCatwalk2(vec2 uv, vec3 worldPosition, vec4 cb[1],\n  sampler2D baseMap, sampler2D detailMap, sampler2D grungeMap) {\n  vec4 base = texture2D(baseMap, uv);\n  vec4 grunge = texture2D(grungeMap, worldPosition.xz * 0.1);\n  vec3 detail = texture2D(detailMap, uv * cb[0].xy).rgb;\n  vec2 detailXY = detail.rg * 2.0 - 1.0;\n  float detailZ = sqrt(max(1.0 - dot(detailXY, detailXY), 0.0));\n  Catwalk2Surface result;\n  result.color = base.b * grunge.rgb;\n  result.smoothness = base.a * grunge.a * detail.b;\n  result.tangentNormal = normalize(vec3(detailXY + base.rg * 2.0 - 1.0, detailZ));\n  // Native ordinary material ID0: metalness0, reflectance0.5 (dielectric F0=.04).\n  // No AO, emissive, opacity or metalness is encoded in these packed inputs.\n  return result;\n}\n";
const ROLES = ['base','detail','grunge'];

export async function prepareRecoveredCatwalk2Materials(document, manager) {
  if (!document?.materials?.length) return { apply() {}, applied: 0, provenance: null };
  const loader = new THREE.TextureLoader(manager), textures = new Map();
  const sources = new Map(Object.values(document.sourceTextures).map(row => [row.url, row]));
  const urls = [...new Set(document.materials.flatMap(row => Object.values(row.textures)))];
  // Bound decoder work while loading the shared textures once per document.
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(4, urls.length) }, async () => {
    while (next < urls.length) {
      const url = urls[next++], source = sources.get(url);
      if (!source) throw new Error(`Missing Catwalk2 texture provenance: ${url}`);
      const texture = await loader.loadAsync(url);
      texture.colorSpace = source.colorSpace === 'srgb' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      texture.flipY = false;
      texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.magFilter = THREE.LinearFilter;
      textures.set(url, texture);
    }
  }));
  const recipes = new Map(document.materials.map(row => [`${row.assetId}/${row.materialId}`, row]));
  let applied = 0;
  return {
    provenance: { evidenceId: document.evidenceId, sections: recipes.size, textures: textures.size, runtimeMapping: document.runtimeMapping, limitations: document.limitations },
    get applied() { return applied; },
    apply(gltf, asset) {
      gltf.scene.traverse(mesh => {
        if (!mesh.isMesh) return;
        for (const material of [].concat(mesh.material)) {
          if (material.userData.recoveredCatwalk2Shader) continue;
          const recipe = recipes.get(`${asset.id}/${material.userData.sourceMaterialId}`);
          if (!recipe) continue;
          if (!mesh.geometry.getAttribute('uv')) throw new Error(`Source Catwalk2 mesh has no UV0: ${asset.id}/${recipe.materialId}`);
          material.color.setRGB(1, 1, 1);
          material.roughness = 1;
          // Native ID0 writes metalness0 and reflectance.5 (dielectric F0=.04).
          material.metalness = 0;
          material.map = material.normalMap = material.roughnessMap = material.metalnessMap = material.aoMap = material.emissiveMap = null;
          material.emissive?.setRGB(0, 0, 0);
          material.userData.recoveredCatwalk2Shader = { evidenceId: document.evidenceId, sourceShader: recipe.sourceShader, runtimeMapping: document.runtimeMapping, nativeLightingInputs: document.nativeLightingInputs };
          material.userData.placeholder = false;
          material.userData.neutralColorApproximation = false;
          configureSourceTangentMaterial(material,mesh.geometry);
          material.onBeforeCompile = function(shader) {
            for (const role of ROLES) shader.uniforms[`bf2_catwalk2_${role}`] = { value: textures.get(recipe.textures[role]) };
            shader.uniforms.bf2_catwalk2_cb = { value: recipe.constants.map(v => new THREE.Vector4(...v)) };
            shader.vertexShader = `varying vec2 bf2_catwalk2_uv;
              varying vec3 bf2_catwalk2_world;
            ` + shader.vertexShader;
            shader.vertexShader = shader.vertexShader.replace('#include <worldpos_vertex>', `#include <worldpos_vertex>
              vec4 bf2_catwalk2_wp = vec4(transformed, 1.0);
              #ifdef USE_INSTANCING
                bf2_catwalk2_wp = instanceMatrix * bf2_catwalk2_wp;
              #endif
              bf2_catwalk2_world = (modelMatrix * bf2_catwalk2_wp).xyz;
              bf2_catwalk2_uv = uv;
            `);
            shader.fragmentShader = `varying vec2 bf2_catwalk2_uv;
              varying vec3 bf2_catwalk2_world;
              uniform vec4 bf2_catwalk2_cb[1];
              ${ROLES.map(role => `uniform sampler2D bf2_catwalk2_${role};`).join('\n')}
              ${CATWALK2_GLSL}
              // Uncovered source layouts retain this derivative frame.
              // Verified geometry selects its original frame below.
              mat3 bf2_catwalk2_tbn(vec3 position, vec3 n, vec2 uvValue) {
                vec3 q0 = dFdx(position), q1 = dFdy(position);
                vec2 st0 = dFdx(uvValue), st1 = dFdy(uvValue);
                vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
                vec3 tangent = q1perp * st0.x + q0perp * st1.x;
                vec3 bitangent = q1perp * st0.y + q0perp * st1.y;
                float invmax = inversesqrt(max(max(dot(tangent, tangent), dot(bitangent, bitangent)), 1e-16));
                return mat3(tangent * invmax, bitangent * invmax, n);
              }
            ` + shader.fragmentShader;
            shader.fragmentShader = shader.fragmentShader.replace('#include <color_fragment>', `#include <color_fragment>
              Catwalk2Surface bf2_catwalk2_surface = sampleCatwalk2(bf2_catwalk2_uv, bf2_catwalk2_world,
                bf2_catwalk2_cb,
                ${ROLES.map(role => `bf2_catwalk2_${role}`).join(', ')});
              diffuseColor.rgb = bf2_catwalk2_surface.color;
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
              roughnessFactor = 1.0 - clamp(bf2_catwalk2_surface.smoothness, 0.0, 1.0);
            `);
            shader.fragmentShader = shader.fragmentShader.replace('#include <normal_fragment_maps>', `
              mat3 bf2_catwalk2_frame = bf2_catwalk2_tbn(-vViewPosition, normal, bf2_catwalk2_uv);
              normal = normalize(bf2_catwalk2_frame * bf2_catwalk2_surface.tangentNormal);
            `);
            if(this.userData.sourceTangentFrame?.enabled){
              shader.vertexShader='varying vec3 bf2_catwalk2_geometricNormal;\n'+shader.vertexShader.replace('#include <worldpos_vertex>',`#include <worldpos_vertex>
                bf2_catwalk2_geometricNormal = inverseTransformDirection(transformedNormal, viewMatrix);
              `);
              shader.fragmentShader='varying vec3 bf2_catwalk2_geometricNormal;\n'+shader.fragmentShader;
              injectSourceTangentFrame(shader,this,'catwalk2');
            }
          };
          material.customProgramCacheKey = function(){return 'bf2-source-SS_CatwalkSystem_Preset_02-2b6d233517-v2|' + sourceTangentProgramKey(this);};
          material.needsUpdate = true;
          applied++;
        }
      });
    },
  };
}
